/* ---------- Allemagne, Autriche, Suisse ---------- */
const D33 = [
{ id:'koenigsberger-klopse', c:'eu', lat:52.520, lon:13.405, base:4, prep:25, cook:30, diff:2, tags:['comfort','sunday','slow'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f2ead6',style:'stew',food:['#f0e8d0','#d8c8a0','#e8dcc0','#8fae7a'],garnish:'#6fbf8f'},
  n:{fr:'Königsberger Klopse',en:'Königsberger Klopse'},
  p:{fr:'Berlin, Allemagne',en:'Berlin, Germany'},
  d:{fr:"Des boulettes de veau pochées dans un bouillon, servies sous une sauce blanche aux câpres et au citron. Venues de Prusse-Orientale avec les réfugiés de 1945, elles sont devenues un classique des cantines berlinoises.",
     en:"Veal dumplings poached in broth and served under a white sauce of capers and lemon. They came from East Prussia with the refugees of 1945 and became a staple of Berlin canteens."},
  i:[['ground_veal',600,'g'],['bread_roll',1,'pc'],['onion',1,'pc'],['anchovy_fillets',3,'pc'],['egg',1,'pc'],['butter',50,'g'],['flour',40,'g'],['capers',60,'g'],['heavy_cream',150,'ml'],['lemon',1,'pc'],['egg_yolk',1,'pc'],['bay_leaf',2,'pc'],['allspice',4,'pc'],['potato',800,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Trempez le petit pain dans l'eau, pressez-le et mélangez-le au veau haché avec l'oignon fondu, les anchois écrasés et l'œuf.","Formez des boulettes de la taille d'une balle de golf et pochez-les 15 minutes dans un bouillon avec laurier et poivre de la Jamaïque, sans ébullition.","Retirez-les et filtrez le bouillon.","Faites un roux blond avec le beurre et la farine, mouillez d'un demi-litre de bouillon et laissez cuire 10 minutes.","Hors du feu, liez avec le jaune battu dans la crème, ajoutez les câpres et le jus de citron, puis replongez-y les boulettes. Servez avec des pommes de terre vapeur."],
     en:["Soak the bread roll in water, squeeze it out and mix into the minced veal with the softened onion, crushed anchovies and egg.","Shape golf-ball dumplings and poach them for 15 minutes in broth with bay and allspice, never boiling.","Lift them out and strain the broth.","Make a pale roux with the butter and flour, whisk in half a litre of broth and cook for 10 minutes.","Off the heat, bind with the yolk beaten into the cream, add the capers and lemon juice, then return the dumplings. Serve with steamed potatoes."]} },

{ id:'maultaschen', c:'eu', lat:48.776, lon:9.183, base:4, prep:60, cook:20, diff:3, tags:['comfort','sunday','pork'],
  art:{v:'bowl',bg:'#2f3328',plate:'#f0e4c8',style:'pastry',food:['#e8dcb8','#c9a878','#f2e8d0','#6f8f4a'],garnish:'#7fae6a'},
  n:{fr:'Maultaschen',en:'Maultaschen'},
  p:{fr:'Stuttgart, Souabe, Allemagne',en:'Stuttgart, Swabia, Germany'},
  d:{fr:"De gros raviolis souabes dont le surnom dit tout : Herrgottsbscheißerle, « les petits trompeurs de Bon Dieu ». Les moines de Maulbronn y cachaient la viande sous les épinards pour la manger en carême.",
     en:"Big Swabian ravioli whose nickname says everything: Herrgottsbscheißerle, 'little cheaters of the Lord'. The monks of Maulbronn hid meat under spinach so they could eat it during Lent."},
  i:[['flour',400,'g'],['egg',4,'pc'],['spinach',400,'g'],['ground_pork',300,'g'],['smoked_bacon',100,'g'],['bread_roll',2,'pc'],['onion',1,'pc'],['parsley',4,'tbsp'],['nutmeg',1,'pinch'],['beef_broth',1.5,'l'],['butter',40,'g'],['marjoram',1,'tsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez la farine et les œufs en une pâte ferme et laissez-la reposer une heure.","Blanchissez les épinards, pressez-les à fond et hachez-les avec le lard et les petits pains trempés.","Mêlez à la viande hachée, à l'oignon fondu, au persil, à la marjolaine et à la muscade.","Étalez la pâte en longues bandes, déposez la farce en boudin, refermez et pressez tous les 6 cm avant de découper.","Pochez 12 minutes dans le bouillon frémissant et servez dans ce bouillon, ou revenus au beurre le lendemain."],
     en:["Knead the flour and eggs into a firm dough and rest it for an hour.","Blanch the spinach, squeeze it thoroughly dry and chop it with the bacon and the soaked bread rolls.","Combine with the minced pork, softened onion, parsley, marjoram and nutmeg.","Roll the dough into long strips, pipe the filling along them, fold over and press every 6 cm before cutting.","Poach for 12 minutes in simmering broth and serve in that broth — or fried in butter the next day."]} },

{ id:'kaesespaetzle', c:'eu', lat:48.401, lon:9.987, base:4, prep:25, cook:20, diff:2, tags:['cheese','comfort','veg'],
  art:{v:'pot',bg:'#33301f',plate:'#f0e2c0',style:'noodle',food:['#e8c46a','#f2dfa8','#c98a2c','#e0a83a'],garnish:'#7fae6a'},
  n:{fr:'Käsespätzle',en:'Käsespätzle'},
  p:{fr:'Ulm, Souabe, Allemagne',en:'Ulm, Swabia, Germany'},
  d:{fr:"Des pâtes fraîches râclées à la planche dans l'eau bouillante, superposées de fromage de montagne et couronnées d'oignons frits. La règle souabe veut qu'on juge une femme à ses Spätzle — le dicton a vieilli, la recette non.",
     en:"Fresh noodles scraped from a board into boiling water, layered with mountain cheese and crowned with fried onions. Swabian lore said you judged a woman by her Spätzle — the saying has aged badly, the recipe has not."},
  i:[['flour',400,'g'],['egg',5,'pc'],['sparkling_water',100,'ml'],['emmental',150,'g'],['appenzeller_cheese',150,'g'],['onion',3,'pc'],['butter',80,'g'],['chives',3,'tbsp'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Battez énergiquement la farine, les œufs, l'eau gazeuse et le sel jusqu'à ce que la pâte fasse des bulles et se détache de la cuillère.","Laissez reposer 20 minutes, puis raclez-la par petites quantités dans une grande casserole d'eau bouillante salée.","Les Spätzle sont cuits dès qu'ils remontent : égouttez-les et rafraîchissez-les à peine.","Faites blondir longuement les oignons émincés dans le beurre, jusqu'à ce qu'ils soient dorés et légèrement croustillants.","Alternez Spätzle et fromages râpés dans un plat chaud, laissez fondre à couvert 5 minutes, puis couvrez d'oignons et de ciboulette."],
     en:["Beat the flour, eggs, sparkling water and salt hard until the batter blisters and pulls away from the spoon.","Rest for 20 minutes, then scrape it in small batches into a large pan of boiling salted water.","The Spätzle are done the moment they float: drain and barely refresh them.","Fry the sliced onions slowly in the butter until golden and lightly crisp.","Layer Spätzle and grated cheeses in a warm dish, cover and let melt for 5 minutes, then top with the onions and chives."]} },

{ id:'schweinshaxe', c:'eu', lat:48.137, lon:11.575, base:4, prep:20, cook:150, diff:2, tags:['pork','slow','festive'],
  art:{v:'board',bg:'#2b2419',plate:'#e8d8b8',style:'grill',food:['#8f5a2b','#c9754a','#3a2a1a','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Schweinshaxe',en:'Schweinshaxe'},
  p:{fr:'Munich, Bavière, Allemagne',en:'Munich, Bavaria, Germany'},
  d:{fr:"Un jarret de porc rôti deux heures et demie, la couenne devenue une carapace de verre qu'il faut casser au couteau. Le plat des brasseries munichoises, arrosé de bière brune pendant la cuisson comme dans le verre.",
     en:"A pork knuckle roasted for two and a half hours, its rind turned into a glassy shell you have to crack with a knife. The dish of Munich beer halls, basted with dark beer during cooking as much as poured beside it."},
  i:[['pork_knuckle',2,'pc'],['brown_ale',500,'ml'],['onion',2,'pc'],['carrot',2,'pc'],['caraway',1,'tbsp'],['garlic',4,'clove'],['coarse_salt',2,'tbsp'],['sauerkraut',600,'g'],['potato',600,'g'],['pepper',null,'']],
  s:{fr:["Incisez la couenne en losanges sans entamer la chair, frottez de sel, d'ail écrasé et de carvi.","Posez les jarrets sur un lit d'oignons et de carottes, versez la moitié de la bière au fond du plat.","Enfournez 2 heures à 160 °C en arrosant toutes les 20 minutes du jus et du reste de bière.","Montez à 220 °C pour les 20 dernières minutes : la couenne cloque et durcit.","Laissez reposer 10 minutes, déglacez le jus de cuisson et servez avec la choucroute et des pommes de terre."],
     en:["Score the rind into diamonds without cutting into the meat, rub with salt, crushed garlic and caraway.","Set the knuckles on a bed of onion and carrot and pour half the beer into the dish.","Roast for 2 hours at 160°C, basting every 20 minutes with the juices and the rest of the beer.","Raise to 220°C for the last 20 minutes: the rind blisters and hardens.","Rest for 10 minutes, deglaze the roasting juices and serve with sauerkraut and potatoes."]} },

{ id:'weisswurst', c:'eu', lat:48.135, lon:11.581, base:4, prep:20, cook:15, diff:2, tags:['pork','breakfast','street'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4ecd8',style:'stew',food:['#f0e8d8','#e8dcc0','#d8c8a0','#c9b48a'],garnish:'#7fae6a'},
  n:{fr:'Weißwurst',en:'Weißwurst'},
  p:{fr:'Munich, Bavière, Allemagne',en:'Munich, Bavaria, Germany'},
  d:{fr:"Une saucisse blanche de veau et de persil, pochée et jamais grillée. La règle munichoise dit qu'elle ne doit pas entendre sonner midi : sans conservateur, on la mangeait le matin même de sa fabrication.",
     en:"A white sausage of veal and parsley, poached and never grilled. Munich lore says it must not hear the noon bells: made without preservatives, it was eaten the very morning it was made."},
  i:[['ground_veal',600,'g'],['pork_fat',200,'g'],['parsley',6,'tbsp'],['onion',1,'pc'],['lemon_zest',1,'pc'],['ice_water',150,'ml'],['white_pepper',1,'tsp'],['nutmeg',1,'pinch'],['sausage_casings',2,'pc'],['sweet_mustard',150,'g'],['brezel',4,'pc'],['salt',null,'']],
  s:{fr:["Mixez le veau et le gras très froids avec l'eau glacée, en plusieurs fois, sans jamais laisser tiédir la masse.","Incorporez le persil haché, l'oignon fondu refroidi, le zeste de citron, le poivre blanc et la muscade.","Embossez dans les boyaux et tordez tous les 12 cm ; piquez les bulles d'air.","Pochez 12 minutes dans une eau à 75 °C : elle ne doit jamais bouillir, sous peine d'éclater les saucisses.","Servez dans leur eau, avec la moutarde douce et un bretzel. On aspire la chair sans manger la peau."],
     en:["Blend the very cold veal and fat with the iced water in several stages, never letting the mixture warm.","Fold in the chopped parsley, cooled softened onion, lemon zest, white pepper and nutmeg.","Fill the casings and twist every 12 cm; prick any air bubbles.","Poach for 12 minutes in water at 75°C: it must never boil, or the sausages burst.","Serve in their water with sweet mustard and a pretzel. You suck out the meat and leave the skin."]} },

{ id:'brezel', c:'eu', lat:48.371, lon:10.898, base:8, prep:40, cook:15, diff:2, tags:['bread','street','bake'],
  art:{v:'board',bg:'#2f2519',plate:'#f0e2c0',style:'flat',food:['#8f5a2b','#c98a4a','#f2e6c8','#e8d8b8'],garnish:'#c9a24a'},
  n:{fr:'Bretzel',en:'Pretzel'},
  p:{fr:'Augsbourg, Bavière, Allemagne',en:'Augsburg, Bavaria, Germany'},
  d:{fr:"Le nœud de pâte trempé dans une solution alcaline avant cuisson : c'est elle qui donne la croûte brune et le goût si particulier. Le ventre craque, les bras restent tendres — un bretzel réussi se reconnaît à ce contraste.",
     en:"The knot of dough dipped in an alkaline bath before baking: that is what gives the brown crust and the unmistakable taste. The belly cracks, the arms stay soft — a good pretzel is known by that contrast."},
  i:[['flour',500,'g'],['water',280,'ml'],['fresh_yeast',20,'g'],['butter',40,'g'],['barley_malt',1,'tbsp'],['baking_soda',60,'g'],['coarse_salt',2,'tbsp'],['salt',10,'g']],
  s:{fr:["Pétrissez farine, eau, levure, beurre, malt et sel 10 minutes en une pâte ferme ; laissez lever 45 minutes.","Divisez en huit, roulez de longs boudins effilés aux extrémités et renflés au centre.","Formez le nœud : croisez les deux bras deux fois et rabattez-les sur le ventre.","Laissez croûter 30 minutes au frais, à découvert, puis plongez chaque bretzel 20 secondes dans un litre d'eau bouillante additionnée du bicarbonate.","Incisez le ventre, salez au gros sel et enfournez 15 minutes à 220 °C."],
     en:["Knead flour, water, yeast, butter, malt and salt for 10 minutes into a firm dough; prove for 45 minutes.","Divide into eight, roll long ropes tapered at the ends and swollen in the middle.","Form the knot: cross the two arms twice and fold them back onto the belly.","Let them dry uncovered in the fridge for 30 minutes, then dip each pretzel for 20 seconds in a litre of boiling water with the bicarbonate.","Slash the belly, scatter coarse salt and bake for 15 minutes at 220°C."]} },

{ id:'rinderrouladen', c:'eu', lat:51.227, lon:6.773, base:4, prep:30, cook:110, diff:2, tags:['beef','slow','sunday'],
  art:{v:'pot',bg:'#2b2419',plate:'#eee0bc',style:'stew',food:['#6f4a2a','#8f5a3a','#c9a878','#3a2a1a'],garnish:'#7fae6a'},
  n:{fr:'Rouleaux de bœuf',en:'Rinderrouladen'},
  p:{fr:'Düsseldorf, Rhénanie, Allemagne',en:'Düsseldorf, Rhineland, Germany'},
  d:{fr:"Une tranche de bœuf enroulée sur de la moutarde, du lard, de l'oignon et un cornichon, braisée deux heures dans son jus. Le déjeuner du dimanche allemand par excellence, avec du chou rouge et des Klöße.",
     en:"A slice of beef rolled around mustard, bacon, onion and a gherkin, braised for two hours in its own juices. The German Sunday lunch par excellence, with red cabbage and potato dumplings."},
  i:[['beef_slices',8,'pc'],['dijon_mustard',4,'tbsp'],['smoked_bacon',150,'g'],['onion',2,'pc'],['pickles',8,'pc'],['carrot',2,'pc'],['tomato_paste',2,'tbsp'],['red_wine',250,'ml'],['beef_broth',500,'ml'],['bay_leaf',2,'pc'],['flour',2,'tbsp'],['butter',40,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Aplatissez les tranches de bœuf, salez, poivrez et tartinez-les de moutarde.","Disposez sur chacune du lard, de l'oignon émincé et un cornichon coupé en deux, puis roulez et fixez avec de la ficelle.","Saisissez les rouleaux de tous côtés dans le beurre chaud et réservez.","Faites revenir carotte et oignon dans la même cocotte, ajoutez le concentré de tomate, déglacez au vin rouge.","Remettez les rouleaux, mouillez de bouillon, ajoutez le laurier et laissez braiser 1 h 45 à couvert. Liez la sauce à la farine délayée."],
     en:["Flatten the beef slices, season and spread them with mustard.","Lay bacon, sliced onion and a halved gherkin on each, roll up and tie with string.","Sear the rolls on all sides in hot butter and set aside.","Sweat carrot and onion in the same pot, add the tomato paste and deglaze with red wine.","Return the rolls, pour in the broth, add the bay and braise covered for 1¾ hours. Thicken the sauce with the slaked flour."]} },

{ id:'labskaus', c:'eu', lat:53.551, lon:9.994, base:4, prep:25, cook:30, diff:1, tags:['sea','comfort','beef'],
  art:{v:'plate',bg:'#2c3440',plate:'#f2ead6',style:'stew',food:['#a8446a','#c9608a','#f0e8d0','#e8c46a'],garnish:'#6fbf8f'},
  n:{fr:'Labskaus',en:'Labskaus'},
  p:{fr:'Hambourg, Allemagne',en:'Hamburg, Germany'},
  d:{fr:"Un hachis rose vif de bœuf salé, de pomme de terre et de betterave, servi avec un œuf au plat, un hareng mariné et un cornichon. Nourriture de marins au long cours : tout y était salé ou en saumure, donc impérissable.",
     en:"A bright pink hash of salt beef, potato and beetroot, served with a fried egg, a pickled herring and a gherkin. Deep-sea sailors' food: everything in it was salted or pickled, and therefore imperishable."},
  i:[['corned_beef',400,'g'],['potato',800,'g'],['beetroot',300,'g'],['onion',2,'pc'],['pickles',4,'pc'],['pickled_herring',4,'pc'],['egg',4,'pc'],['pickle_brine',100,'ml'],['lard',40,'g'],['bay_leaf',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire les pommes de terre à l'eau salée avec le laurier, puis écrasez-les grossièrement.","Faites fondre l'oignon dans le saindoux, ajoutez le bœuf salé effiloché et la betterave cuite en petits dés.","Mêlez aux pommes de terre, mouillez du jus de cornichons et laissez chauffer 10 minutes en remuant : le hachis doit rester grossier.","Faites frire les œufs au plat, blanc pris et jaune coulant.","Dressez le hachis en dôme, posez l'œuf dessus, le hareng et le cornichon à côté."],
     en:["Boil the potatoes in salted water with the bay leaf, then crush them roughly.","Soften the onion in the lard, add the shredded salt beef and the cooked beetroot in small dice.","Fold into the potato, moisten with the pickle brine and heat through for 10 minutes, stirring: the hash should stay coarse.","Fry the eggs, whites set and yolks running.","Mound the hash on the plate, set the egg on top, herring and gherkin alongside."]} },

{ id:'gruenkohl-pinkel', c:'eu', lat:53.079, lon:8.802, base:6, prep:30, cook:120, diff:1, tags:['comfort','slow','pork'],
  art:{v:'pot',bg:'#28331f',plate:'#eee0bc',style:'stew',food:['#4f6f3a','#3a5a2a','#c9a878','#8f6a4a'],garnish:'#7fae6a'},
  n:{fr:'Chou frisé et saucisse Pinkel',en:'Grünkohl mit Pinkel'},
  p:{fr:'Brême, Allemagne',en:'Bremen, Germany'},
  d:{fr:"Le chou frisé attend la première gelée pour être cueilli : le froid transforme son amidon en sucre. On le mijote deux heures avec du lard et la Pinkel, saucisse fumée à l'avoine, au cours d'excursions rituelles de janvier.",
     en:"The kale waits for the first frost before it is picked: cold turns its starch into sugar. It is stewed for two hours with bacon and Pinkel, a smoked oat sausage, during the ritual outings of January."},
  i:[['curly_kale',1.5,'kg'],['pinkel_sausage',4,'pc'],['smoked_pork_collar',600,'g'],['smoked_bacon',150,'g'],['onion',2,'pc'],['lard',60,'g'],['oats',3,'tbsp'],['mustard',2,'tbsp'],['beef_broth',500,'ml'],['potato',800,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Équeutez le chou, blanchissez-le 5 minutes et hachez-le grossièrement.","Faites fondre l'oignon et le lard dans le saindoux, ajoutez le chou et laissez-le suer 10 minutes.","Mouillez de bouillon, enfouissez la viande fumée et laissez mijoter 1 heure à couvert.","Posez les saucisses Pinkel sur le chou sans les piquer et poursuivez 45 minutes : leur gras parfume tout le plat.","Liez avec l'avoine, relevez de moutarde et servez avec des pommes de terre rissolées."],
     en:["Strip the kale from its stalks, blanch for 5 minutes and chop it coarsely.","Soften the onion and bacon in the lard, add the kale and let it sweat for 10 minutes.","Moisten with broth, bury the smoked pork and simmer covered for 1 hour.","Lay the Pinkel sausages on the kale without pricking them and continue for 45 minutes: their fat perfumes the whole dish.","Thicken with the oats, sharpen with mustard and serve with fried potatoes."]} },

{ id:'handkaese-mit-musik', c:'eu', lat:50.111, lon:8.682, base:4, prep:15, cook:0, diff:1, tags:['cheese','fresh','fast'],
  art:{v:'plate',bg:'#2f3326',plate:'#f2e8d0',style:'salad',food:['#e8d8a8','#f0e4c0','#c9b47a','#8fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Handkäse mit Musik',en:'Handkäse mit Musik'},
  p:{fr:'Francfort, Hesse, Allemagne',en:'Frankfurt, Hesse, Germany'},
  d:{fr:"Un fromage aigre translucide, marié à une marinade d'oignon cru et de vinaigre. La « musique » du nom n'a rien de poétique : c'est ce que produisent les oignons quelques heures plus tard, et les Hessois en rient encore.",
     en:"A translucent sour cheese married to a marinade of raw onion and vinegar. The 'music' of the name is not poetic: it is what the onions produce a few hours later, and the Hessians still find it funny."},
  i:[['handkaese',400,'g'],['onion',3,'pc'],['cider_vinegar',80,'ml'],['olive_oil',40,'ml'],['caraway',1,'tsp'],['chives',3,'tbsp'],['rye_bread',8,'slice'],['butter',60,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Émincez les oignons le plus finement possible et salez-les légèrement.","Mêlez-les au vinaigre, à l'huile, au carvi et à un peu de poivre.","Disposez les fromages dans un plat creux et couvrez-les entièrement de cette marinade.","Laissez reposer au frais au moins 4 heures, idéalement une nuit : le fromage doit s'imprégner sans se défaire.","Servez avec du pain de seigle beurré et beaucoup de ciboulette. Un verre de cidre de pommes est de rigueur."],
     en:["Slice the onions as finely as you can and salt them lightly.","Mix them with the vinegar, oil, caraway and a little pepper.","Lay the cheeses in a deep dish and cover them entirely with this marinade.","Rest in the fridge for at least 4 hours, ideally overnight: the cheese should soak without falling apart.","Serve with buttered rye bread and plenty of chives. A glass of apple cider is obligatory."]} },

{ id:'thueringer-rostbratwurst', c:'eu', lat:50.978, lon:11.029, base:4, prep:20, cook:15, diff:1, tags:['pork','grill','street'],
  art:{v:'board',bg:'#2b2419',plate:'#e8d8b8',style:'grill',food:['#c9754a','#8f5a2b','#e8d8b8','#3a2a1a'],garnish:'#7fae6a'},
  n:{fr:'Saucisse grillée de Thuringe',en:'Thüringer Rostbratwurst'},
  p:{fr:'Erfurt, Thuringe, Allemagne',en:'Erfurt, Thuringia, Germany'},
  d:{fr:"Attestée dès 1404 dans les comptes d'un couvent d'Arnstadt, elle se grille sur la braise de pomme de pin et se mange debout, dans un petit pain trop court pour elle, avec de la moutarde brune.",
     en:"Recorded as early as 1404 in the accounts of a convent in Arnstadt, it is grilled over pine-cone embers and eaten standing, in a roll too short for it, with brown mustard."},
  i:[['ground_pork',800,'g'],['pork_fat',150,'g'],['caraway',2,'tsp'],['marjoram',2,'tsp'],['garlic',2,'clove'],['nutmeg',1,'pinch'],['sausage_casings',2,'pc'],['bread_roll',4,'pc'],['mustard',4,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Hachez la viande et le gras à la grille moyenne, en gardant tout très froid.","Assaisonnez de carvi, marjolaine, ail, muscade, sel et poivre, et travaillez la masse jusqu'à ce qu'elle devienne collante.","Embossez sans serrer et tordez tous les 20 cm ; laissez reposer une nuit au frais.","Grillez sur braise moyenne 12 à 15 minutes en tournant souvent : la peau doit brunir sans éclater.","Servez dans un petit pain fendu, avec une cuillerée de moutarde brune."],
     en:["Mince the meat and fat on a medium plate, keeping everything very cold.","Season with caraway, marjoram, garlic, nutmeg, salt and pepper, and work the mixture until it turns tacky.","Fill the casings loosely and twist every 20 cm; rest overnight in the fridge.","Grill over medium embers for 12 to 15 minutes, turning often: the skin should brown without splitting.","Serve in a split roll with a spoonful of brown mustard."]} },

{ id:'spargel-hollandaise', c:'eu', lat:52.234, lon:12.972, base:4, prep:25, cook:20, diff:2, tags:['veg','fresh','festive'],
  art:{v:'plate',bg:'#2c3440',plate:'#f4ecd8',style:'salad',food:['#f0e8d0','#e8dcb8','#e8c46a','#d8c8a0'],garnish:'#7fae6a'},
  n:{fr:'Asperges blanches, sauce hollandaise',en:'White asparagus with hollandaise'},
  p:{fr:'Beelitz, Brandebourg, Allemagne',en:'Beelitz, Brandenburg, Germany'},
  d:{fr:"D'avril à la Saint-Jean, l'Allemagne s'arrête pour l'asperge blanche. À Beelitz, on la cueille avant qu'elle ne perce le sable, ce qui lui garde sa blancheur et sa douceur. Beurre, jambon, pommes vapeur : rien de plus.",
     en:"From April to Midsummer, Germany stops for white asparagus. At Beelitz it is cut before it breaks the sand, which keeps it white and sweet. Butter, ham, steamed potatoes: nothing more."},
  i:[['white_asparagus',2,'kg'],['butter',250,'g'],['egg_yolk',4,'pc'],['lemon',1,'pc'],['white_wine',50,'ml'],['sugar',1,'tsp'],['potato',800,'g'],['ham',200,'g'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Épluchez les asperges de la pointe vers la base, deux fois plutôt qu'une, et cassez le talon fibreux.","Faites cuire les épluchures 15 minutes dans l'eau salée avec le sucre : ce bouillon servira à cuire les asperges.","Pochez-les 12 à 18 minutes selon leur grosseur ; elles doivent plier sans casser.","Clarifiez le beurre. Fouettez les jaunes avec le vin au bain-marie jusqu'au ruban, puis versez le beurre tiède en filet sans cesser de fouetter.","Assaisonnez la sauce de citron, sel et muscade, et servez les asperges avec le jambon et les pommes vapeur."],
     en:["Peel the asparagus from tip to base, twice rather than once, and snap off the fibrous end.","Simmer the peelings for 15 minutes in salted water with the sugar: this broth will cook the spears.","Poach them 12 to 18 minutes depending on thickness; they should bend without snapping.","Clarify the butter. Whisk the yolks with the wine over a bain-marie to the ribbon, then trickle in the warm butter, whisking without pause.","Season the sauce with lemon, salt and nutmeg, and serve the asparagus with the ham and steamed potatoes."]} },

{ id:'saumagen', c:'eu', lat:49.462, lon:8.169, base:8, prep:45, cook:180, diff:3, tags:['pork','slow','sunday'],
  art:{v:'board',bg:'#2f2a20',plate:'#eee0bc',style:'grill',food:['#c9a878','#8f5a3a','#e8d8b8','#6f8f4a'],garnish:'#7fae6a'},
  n:{fr:'Saumagen du Palatinat',en:'Palatinate Saumagen'},
  p:{fr:'Bad Dürkheim, Palatinat, Allemagne',en:'Bad Dürkheim, Palatinate, Germany'},
  d:{fr:"Une panse de porc farcie de viande et de pommes de terre, pochée puis tranchée et poêlée. Helmut Kohl l'a servie à Gorbatchev, Thatcher et Reagan : le plat paysan le plus diplomatique d'Allemagne.",
     en:"A pig's stomach stuffed with meat and potato, poached then sliced and pan-fried. Helmut Kohl served it to Gorbachev, Thatcher and Reagan: the most diplomatic peasant dish in Germany."},
  i:[['pork_stomach',1,'pc'],['pork_shoulder',700,'g'],['potato',800,'g'],['onion',2,'pc'],['egg',2,'pc'],['marjoram',2,'tsp'],['nutmeg',1,'pinch'],['white_pepper',1,'tsp'],['lard',60,'g'],['sauerkraut',600,'g'],['white_wine',200,'ml'],['salt',null,'']],
  s:{fr:["Nettoyez longuement la panse à l'eau vinaigrée et laissez-la tremper une nuit.","Coupez le porc et les pommes de terre cuites en gros dés, mêlez à l'oignon fondu, aux œufs, à la marjolaine et aux épices.","Remplissez la panse aux trois quarts seulement — la farce gonfle — et cousez l'ouverture.","Pochez 2 h 30 dans une eau à 80 °C, sans ébullition, en piquant deux ou trois fois pour éviter qu'elle n'éclate.","Laissez refroidir, tranchez en rondelles épaisses et faites-les dorer au saindoux. Servez avec la choucroute au vin blanc."],
     en:["Clean the stomach thoroughly in vinegared water and soak it overnight.","Cut the pork and boiled potatoes into large dice, mix with the softened onion, eggs, marjoram and spices.","Fill the stomach only three quarters full — the stuffing swells — and sew the opening shut.","Poach for 2½ hours in water at 80°C, never boiling, pricking it two or three times so it does not burst.","Cool, cut into thick slices and fry them golden in lard. Serve with sauerkraut cooked in white wine."]} },

{ id:'himmel-und-erde', c:'eu', lat:50.930, lon:6.950, base:4, prep:20, cook:35, diff:1, tags:['comfort','pork','fruit'],
  art:{v:'plate',bg:'#2b2a1c',plate:'#f0e4c8',style:'stew',food:['#e8dcb8','#8f3b4a','#e0b45a','#c9a878'],garnish:'#7fae6a'},
  n:{fr:'Ciel et Terre',en:'Himmel und Erde'},
  p:{fr:'Cologne, Rhénanie, Allemagne',en:'Cologne, Rhineland, Germany'},
  d:{fr:"Le ciel, ce sont les pommes qui poussent en hauteur ; la terre, les pommes de terre. Écrasées ensemble et couronnées de boudin noir poêlé et d'oignons frits, elles font un plat rhénan attesté depuis le XVIIIe siècle.",
     en:"Heaven is the apples that grow above; earth is the potatoes below. Mashed together and crowned with fried black pudding and onions, they make a Rhineland dish recorded since the 18th century."},
  i:[['potato',800,'g'],['apple',600,'g'],['blood_sausage',600,'g'],['onion',3,'pc'],['smoked_bacon',100,'g'],['butter',60,'g'],['sugar',1,'tbsp'],['cider_vinegar',1,'tbsp'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Cuisez les pommes de terre à l'eau salée. En parallèle, faites compoter les pommes en quartiers avec le sucre et le vinaigre.","Écrasez les deux ensemble à la fourchette, en gardant du corps, et assaisonnez de muscade.","Faites blondir les oignons émincés dans le beurre jusqu'à ce qu'ils dorent, avec le lard en dés.","Coupez le boudin en tranches épaisses et poêlez-les 2 minutes par face, sans les retourner davantage.","Dressez l'écrasée, posez le boudin, couvrez d'oignons et de lardons croustillants."],
     en:["Boil the potatoes in salted water. Meanwhile stew the quartered apples with the sugar and vinegar.","Mash the two together with a fork, keeping some texture, and season with nutmeg.","Fry the sliced onions in the butter until golden, along with the diced bacon.","Cut the black pudding into thick slices and fry for 2 minutes a side, turning no more than once.","Spoon out the mash, lay on the pudding and cover with the onions and crisp bacon."]} },

{ id:'stollen', c:'eu', lat:51.050, lon:13.738, base:10, prep:60, cook:60, diff:3, tags:['sweet','festive','bake'],
  art:{v:'board',bg:'#2e2419',plate:'#f4ead4',style:'cake',food:['#f4f0e6','#c9a878','#e0b45a','#8f6a4a'],garnish:'#c9754a'},
  n:{fr:'Stollen de Dresde',en:'Dresden Stollen'},
  p:{fr:'Dresde, Saxe, Allemagne',en:'Dresden, Saxony, Germany'},
  d:{fr:"Un pain de Noël lourd de fruits et de beurre, dont la forme évoque l'enfant emmailloté. Jusqu'en 1491, le beurre y était interdit pendant l'Avent : il fallut une bulle papale pour l'autoriser.",
     en:"A Christmas loaf heavy with fruit and butter, its shape recalling the swaddled child. Until 1491 butter was forbidden in it during Advent: it took a papal bull to allow it."},
  i:[['flour',700,'g'],['fresh_yeast',40,'g'],['whole_milk',250,'ml'],['butter',350,'g'],['sugar',120,'g'],['raisins',400,'g'],['dark_rum',100,'ml'],['candied_fruit',150,'g'],['almonds',150,'g'],['marzipan',200,'g'],['lemon_zest',2,'pc'],['cardamom',1,'tsp'],['nutmeg',1,'pinch'],['powdered_sugar',150,'g'],['salt',null,'']],
  s:{fr:["Faites macérer les raisins dans le rhum au moins une nuit, deux si vous le pouvez.","Préparez un levain avec la levure, le lait tiède et un peu de farine ; laissez-le mousser 20 minutes.","Pétrissez avec le reste de farine, 200 g de beurre, le sucre et les épices, puis incorporez fruits et amandes sans déchirer la pâte.","Laissez lever une heure, aplatissez, posez un boudin de pâte d'amandes au centre et repliez la pâte dessus en décalé.","Enfournez 60 minutes à 160 °C, badigeonnez de beurre fondu à la sortie et enrobez de sucre glace. Attendez trois semaines avant de le trancher."],
     en:["Steep the raisins in the rum for at least one night, two if you can.","Make a starter with the yeast, warm milk and a little flour; let it froth for 20 minutes.","Knead with the remaining flour, 200 g of butter, the sugar and the spices, then work in the fruit and almonds without tearing the dough.","Prove for an hour, flatten, lay a rope of marzipan down the middle and fold the dough over it, off-centre.","Bake for 60 minutes at 160°C, brush with melted butter as it comes out and bury it in icing sugar. Wait three weeks before slicing."]} },

{ id:'rote-gruetze', c:'eu', lat:54.323, lon:10.135, base:6, prep:15, cook:15, diff:1, tags:['sweet','fruit','fast'],
  art:{v:'bowl',bg:'#2c2434',plate:'#f4ecd8',style:'cake',food:['#a8203a','#c9402c','#f0e8d0','#8f1a3a'],garnish:'#f0e8d0'},
  n:{fr:'Rote Grütze',en:'Rote Grütze'},
  p:{fr:'Kiel, Schleswig-Holstein, Allemagne',en:'Kiel, Schleswig-Holstein, Germany'},
  d:{fr:"Une compote de fruits rouges à peine liée, servie glacée sous un voile de crème froide ou de sauce vanille. Le dessert de l'été du Nord, où la saison des baies est brève et l'on ne gâche rien.",
     en:"A barely thickened compote of red fruit, served ice cold beneath a veil of cold cream or vanilla sauce. The summer dessert of the North, where the berry season is short and nothing is wasted."},
  i:[['redcurrants',400,'g'],['raspberries',300,'g'],['strawberries',300,'g'],['morello_cherries',200,'g'],['sugar',150,'g'],['cornstarch',40,'g'],['water',300,'ml'],['vanilla',1,'tsp'],['lemon',1,'pc'],['heavy_cream',200,'ml']],
  s:{fr:["Équeutez les fruits et dénoyautez les cerises ; réservez un quart des framboises pour la fin.","Portez l'eau, le sucre et le jus de citron à ébullition, ajoutez les groseilles et les cerises et laissez cuire 5 minutes.","Ajoutez fraises et framboises et retirez du feu presque aussitôt : elles ne doivent pas fondre.","Délayez la fécule dans un peu d'eau froide, versez-la dans le fruit chaud et laissez épaissir 1 minute à peine.","Ajoutez la vanille et les framboises réservées, laissez refroidir puis 4 heures au frais. Servez avec la crème froide à part."],
     en:["Hull the fruit and stone the cherries; keep a quarter of the raspberries back for the end.","Bring the water, sugar and lemon juice to the boil, add the currants and cherries and cook for 5 minutes.","Add the strawberries and raspberries and take off the heat almost at once: they must not collapse.","Slake the cornstarch in a little cold water, stir it into the hot fruit and let it thicken for barely a minute.","Add the vanilla and the reserved raspberries, cool, then chill for 4 hours. Serve with cold cream on the side."]} },

{ id:'tafelspitz', c:'eu', lat:48.210, lon:16.363, base:6, prep:30, cook:180, diff:2, tags:['beef','slow','sunday'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4ecd8',style:'soup',food:['#e8dcc0','#c9a878','#f0e8d0','#8fae7a'],garnish:'#6fbf8f'},
  n:{fr:'Tafelspitz',en:'Tafelspitz'},
  p:{fr:'Vienne, Autriche',en:'Vienna, Austria'},
  d:{fr:"Le morceau de bœuf le plus prisé de Vienne, poché trois heures et servi dans son bouillon avec deux sauces : raifort à la pomme et ciboulette. C'était le plat préféré de François-Joseph, qui en mangeait presque chaque jour.",
     en:"The most prized cut of beef in Vienna, poached for three hours and served in its broth with two sauces: horseradish with apple, and chive. It was Franz Joseph's favourite dish, eaten almost daily."},
  i:[['beef_rump',1.5,'kg'],['beef_bones',500,'g'],['carrot',3,'pc'],['celery_root',1,'pc'],['leek',2,'pc'],['onion',2,'pc'],['bay_leaf',2,'pc'],['black_peppercorns',1,'tbsp'],['horseradish',150,'g'],['apple',2,'pc'],['chives',1,'bunch'],['heavy_cream',150,'ml'],['bread',2,'slice'],['potato',800,'g'],['salt',null,'']],
  s:{fr:["Faites brunir à sec les oignons coupés en deux, face contre la plaque : c'est ce qui donne au bouillon sa couleur d'or.","Portez la viande et les os à frémissement dans une grande eau, écumez soigneusement pendant vingt minutes.","Ajoutez légumes, laurier et poivre, et laissez pocher 2 h 30 sans jamais bouillir.","Râpez le raifort dans la pomme cuite et un peu de bouillon pour la première sauce ; mixez la ciboulette, la crème et le pain trempé pour la seconde.","Tranchez la viande contre le fil, servez-la dans une soupière avec le bouillon, les légumes, et les deux sauces à part."],
     en:["Brown the halved onions dry, cut side down on the pan: this is what gives the broth its golden colour.","Bring the meat and bones to a bare simmer in plenty of water, skimming carefully for twenty minutes.","Add the vegetables, bay and peppercorns, and poach for 2½ hours, never boiling.","Grate the horseradish into cooked apple and a little broth for the first sauce; blend chives, cream and soaked bread for the second.","Carve the meat against the grain, serve it in a tureen with the broth and vegetables, the two sauces alongside."]} },

{ id:'kaiserschmarrn', c:'eu', lat:47.809, lon:13.055, base:4, prep:20, cook:20, diff:2, tags:['sweet','comfort','fast'],
  art:{v:'plate',bg:'#332a1e',plate:'#f4ead4',style:'cake',food:['#f0e0bc','#e0b45a','#f4f0e6','#8f3b4a'],garnish:'#c9754a'},
  n:{fr:'Kaiserschmarrn',en:'Kaiserschmarrn'},
  p:{fr:'Salzbourg, Autriche',en:'Salzburg, Austria'},
  d:{fr:"Une crêpe épaisse déchirée à la spatule en lambeaux dorés, caramélisée au sucre et servie avec une compote de prunes. Le « gribouillis de l'Empereur » : la légende veut qu'un cuisinier ait raté sa crêpe devant François-Joseph.",
     en:"A thick pancake torn into golden shreds with a spatula, caramelised in sugar and served with plum compote. The 'Emperor's scramble': legend has a cook botching his pancake in front of Franz Joseph."},
  i:[['flour',200,'g'],['whole_milk',300,'ml'],['egg',5,'pc'],['sugar',60,'g'],['raisins',60,'g'],['dark_rum',50,'ml'],['butter',80,'g'],['vanilla',1,'tsp'],['powdered_sugar',3,'tbsp'],['plum_jam',250,'g'],['salt',null,'']],
  s:{fr:["Faites gonfler les raisins dans le rhum tiède.","Fouettez les jaunes, le lait, la farine, la vanille et une pincée de sel en une pâte lisse ; laissez reposer 15 minutes.","Montez les blancs en neige avec la moitié du sucre et incorporez-les délicatement.","Versez dans une grande poêle beurrée, parsemez de raisins et laissez prendre 4 minutes, puis retournez d'un bloc.","Déchirez la crêpe en morceaux à la spatule, saupoudrez du sucre restant et laissez caraméliser 3 minutes en remuant. Poudrez de sucre glace, servez avec la compote."],
     en:["Plump the raisins in the warm rum.","Whisk the yolks, milk, flour, vanilla and a pinch of salt to a smooth batter; rest for 15 minutes.","Beat the whites to soft peaks with half the sugar and fold them in gently.","Pour into a large buttered pan, scatter the raisins over and let it set for 4 minutes, then flip it in one piece.","Tear the pancake into pieces with the spatula, sprinkle with the remaining sugar and caramelise for 3 minutes, stirring. Dust with icing sugar and serve with the compote."]} },

{ id:'apfelstrudel', c:'eu', lat:48.205, lon:16.380, base:8, prep:60, cook:40, diff:3, tags:['sweet','bake','fruit'],
  art:{v:'board',bg:'#2f2519',plate:'#f4ead4',style:'pastry',food:['#e8d8b8','#c9a24a','#f2e6c8','#8f6a4a'],garnish:'#c9754a'},
  n:{fr:'Strudel aux pommes',en:'Apfelstrudel'},
  p:{fr:'Vienne, Autriche',en:'Vienna, Austria'},
  d:{fr:"La pâte doit être étirée à la main sur une nappe jusqu'à ce qu'on puisse lire un journal au travers — la règle est viennoise et sans appel. Elle arrive de Turquie via la Hongrie, cousine lointaine du baklava.",
     en:"The dough must be stretched by hand over a tablecloth until you can read a newspaper through it — the Viennese rule allows no appeal. It came from Turkey by way of Hungary, a distant cousin of baklava."},
  i:[['flour',250,'g'],['water',120,'ml'],['olive_oil',40,'ml'],['apple',1.2,'kg'],['breadcrumbs',80,'g'],['butter',150,'g'],['sugar',120,'g'],['raisins',80,'g'],['dark_rum',50,'ml'],['cinnamon',2,'tsp'],['walnuts',60,'g'],['lemon',1,'pc'],['powdered_sugar',3,'tbsp'],['salt',null,'']],
  s:{fr:["Pétrissez farine, eau tiède, huile et sel 10 minutes jusqu'à ce que la pâte devienne élastique et brillante ; huilez-la et laissez-la reposer une heure sous un bol chaud.","Faites dorer la chapelure dans la moitié du beurre : elle absorbera le jus des pommes.","Épluchez et taillez les pommes en fines lamelles, mêlez-les au sucre, à la cannelle, aux raisins au rhum, aux noix et au citron.","Étirez la pâte à la main sur une nappe farinée jusqu'à la transparence, badigeonnez de beurre fondu et étalez la chapelure.","Déposez les pommes sur un tiers, roulez en vous aidant de la nappe, soudez les bouts et enfournez 40 minutes à 190 °C en badigeonnant deux fois de beurre."],
     en:["Knead flour, warm water, oil and salt for 10 minutes until the dough is elastic and glossy; oil it and rest it for an hour under a warm bowl.","Toast the breadcrumbs in half the butter: they will absorb the apple juices.","Peel and thinly slice the apples, mix with the sugar, cinnamon, rum-soaked raisins, walnuts and lemon.","Stretch the dough by hand over a floured cloth until translucent, brush with melted butter and scatter the crumbs.","Lay the apples along one third, roll up using the cloth, seal the ends and bake for 40 minutes at 190°C, brushing twice with butter."]} },

{ id:'tiroler-groestl', c:'eu', lat:47.269, lon:11.404, base:4, prep:15, cook:25, diff:1, tags:['comfort','beef','fast'],
  art:{v:'pot',bg:'#2b2419',plate:'#eee0bc',style:'stew',food:['#c9a24a','#8f5a3a','#e8d8b8','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Gröstl tyrolien',en:'Tiroler Gröstl'},
  p:{fr:'Innsbruck, Tyrol, Autriche',en:'Innsbruck, Tyrol, Austria'},
  d:{fr:"Le repas des restes, fait à la poêle : pommes de terre de la veille, viande bouillie du dimanche, oignon, tout rissolé ensemble et couronné d'un œuf au plat. Le déjeuner des refuges après une matinée de montagne.",
     en:"The leftover meal, made in a pan: yesterday's potatoes, Sunday's boiled beef, onion, all fried together and crowned with a fried egg. The refuge lunch after a morning in the mountains."},
  i:[['potato',800,'g'],['beef_round',400,'g'],['onion',2,'pc'],['smoked_bacon',100,'g'],['lard',50,'g'],['egg',4,'pc'],['caraway',1,'tsp'],['marjoram',1,'tsp'],['parsley',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire les pommes de terre en robe des champs la veille : froides, elles ne se déferont pas à la poêle.","Épluchez-les, coupez-les en rondelles épaisses et faites-les rissoler dans le saindoux jusqu'à ce qu'elles dorent.","Ajoutez le lard et l'oignon émincé, laissez colorer sans remuer trop souvent.","Incorporez le bœuf bouilli en lamelles, le carvi et la marjolaine, et laissez chauffer 5 minutes.","Faites quatre œufs au plat et posez-les sur le gröstl, persil par-dessus. Servez dans la poêle."],
     en:["Boil the potatoes in their skins the day before: cold, they will not fall apart in the pan.","Peel them, cut into thick rounds and fry them in lard until golden.","Add the bacon and sliced onion, letting them colour without stirring too often.","Fold in the sliced boiled beef, the caraway and the marjoram, and heat through for 5 minutes.","Fry four eggs and lay them on the gröstl, parsley over the top. Serve in the pan."]} },

{ id:'steirisches-backhendl', c:'eu', lat:47.071, lon:15.439, base:4, prep:30, cook:20, diff:2, tags:['poultry','fry','sunday'],
  art:{v:'plate',bg:'#2f3326',plate:'#f2e6c8',style:'pastry',food:['#e0b45a','#c98a2c','#f0d89a','#8fae5a'],garnish:'#7fae6a'},
  n:{fr:'Poulet frit de Styrie',en:'Styrian Backhendl'},
  p:{fr:'Graz, Styrie, Autriche',en:'Graz, Styria, Austria'},
  d:{fr:"Un poulet découpé, pané et frit au saindoux, servi tiède avec une salade de pommes de terre à l'huile de courge grillée. Au XVIIIe siècle, seule l'aristocratie viennoise pouvait s'offrir un poulet entier pour une seule personne.",
     en:"A jointed chicken, breaded and fried in lard, served warm with potato salad dressed in roasted pumpkin-seed oil. In the 18th century only the Viennese aristocracy could afford a whole chicken for one person."},
  i:[['chicken',1.4,'kg'],['flour',150,'g'],['egg',3,'pc'],['breadcrumbs',250,'g'],['lard',1,'kg'],['lemon',2,'pc'],['potato',800,'g'],['pumpkin_seed_oil',60,'ml'],['cider_vinegar',40,'ml'],['onion',1,'pc'],['parsley',4,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Découpez le poulet en huit morceaux, salez et laissez reposer 30 minutes.","Passez chaque morceau dans la farine, l'œuf battu puis la chapelure, sans presser : la panure doit rester lâche pour souffler à la friture.","Chauffez le saindoux à 165 °C et faites frire les morceaux 12 à 15 minutes selon leur taille.","Égouttez sur une grille, jamais sur du papier, pour garder la panure croustillante.","Préparez la salade de pommes de terre tièdes à l'oignon, au vinaigre et à l'huile de pépins de courge, et servez avec des quartiers de citron."],
     en:["Joint the chicken into eight pieces, salt them and rest for 30 minutes.","Coat each piece in flour, beaten egg and breadcrumbs, without pressing: the crumb must stay loose so it puffs in the fat.","Heat the lard to 165°C and fry the pieces for 12 to 15 minutes depending on size.","Drain on a rack, never on paper, to keep the crust crisp.","Make the warm potato salad with onion, vinegar and pumpkin-seed oil, and serve with lemon wedges."]} },

{ id:'roesti', c:'eu', lat:46.948, lon:7.447, base:4, prep:20, cook:30, diff:2, tags:['veg','comfort','breakfast'],
  art:{v:'plate',bg:'#33301f',plate:'#f0e2c0',style:'flat',food:['#e0b45a','#c98a2c','#f2dfa8','#8f6a2b'],garnish:'#7fae6a'},
  n:{fr:'Rösti',en:'Rösti'},
  p:{fr:'Berne, Suisse',en:'Bern, Switzerland'},
  d:{fr:"Une galette de pommes de terre râpées dorée dans le beurre, à l'origine le petit-déjeuner des paysans bernois. La ligne imaginaire qui sépare la Suisse romande de la Suisse alémanique s'appelle encore le « Röstigraben ».",
     en:"A cake of grated potato browned in butter, originally the breakfast of Bernese farmers. The imaginary line dividing French- from German-speaking Switzerland is still called the 'Röstigraben'."},
  i:[['potato',1,'kg'],['butter',80,'g'],['lard',30,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire les pommes de terre en robe des champs la veille et laissez-les refroidir une nuit entière : c'est la seule règle qui compte.","Épluchez-les et râpez-les à la grille épaisse, sans les écraser.","Salez au dernier moment, jamais avant : le sel ferait rendre l'eau et la galette resterait molle.","Versez dans une poêle beurrée bien chaude, tassez légèrement et laissez prendre 15 minutes à feu moyen.","Retournez à l'aide d'une assiette, ajoutez le reste de beurre et dorez 12 minutes de l'autre côté. La croûte doit être uniforme et cassante."],
     en:["Boil the potatoes in their skins the day before and leave them to cool overnight: this is the only rule that matters.","Peel and grate them on the coarse side of the grater, without crushing them.","Salt at the last moment, never before: salt would draw out water and the cake would stay soft.","Tip into a hot buttered pan, press down lightly and let it set for 15 minutes over medium heat.","Turn it with a plate, add the remaining butter and brown the other side for 12 minutes. The crust should be even and brittle."]} },

{ id:'zuercher-geschnetzeltes', c:'eu', lat:47.377, lon:8.542, base:4, prep:20, cook:20, diff:2, tags:['comfort','fast','sunday'],
  art:{v:'plate',bg:'#2c3440',plate:'#f4ecd8',style:'stew',food:['#e8dcc0','#c9a878','#f0e8d0','#8f6a4a'],garnish:'#7fae6a'},
  n:{fr:'Émincé à la zurichoise',en:'Zürcher Geschnetzeltes'},
  p:{fr:'Zurich, Suisse',en:'Zurich, Switzerland'},
  d:{fr:"Du veau taillé en fines lanières, saisi très vite et nappé d'une sauce à la crème et au vin blanc. À Zurich, on y ajoute les rognons ; ailleurs, on s'en dispense. Il se sert toujours avec des rösti.",
     en:"Veal cut into fine strips, seared very fast and coated in a cream and white wine sauce. In Zurich the kidneys go in; elsewhere they are left out. It is always served with rösti."},
  i:[['veal_escalope',700,'g'],['pork_kidney',150,'g'],['button_mushrooms',300,'g'],['shallot',2,'pc'],['white_wine',150,'ml'],['heavy_cream',250,'ml'],['butter',60,'g'],['flour',2,'tbsp'],['lemon',1,'pc'],['parsley',4,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez le veau en lanières de la largeur d'un doigt et farinez-les très légèrement.","Saisissez-les en deux fois dans le beurre brûlant, 90 secondes à peine, et réservez-les au chaud : elles finiront de cuire dans la sauce.","Faites suer l'échalote, ajoutez les champignons émincés et laissez-les rendre leur eau.","Déglacez au vin blanc, laissez réduire de moitié, versez la crème et laissez épaissir 5 minutes.","Remettez la viande et son jus, chauffez sans bouillir, relevez de citron et de persil."],
     en:["Cut the veal into finger-width strips and flour them very lightly.","Sear them in two batches in sizzling butter, barely 90 seconds, and keep them warm: they will finish cooking in the sauce.","Sweat the shallot, add the sliced mushrooms and let them release their water.","Deglaze with white wine, reduce by half, pour in the cream and let it thicken for 5 minutes.","Return the meat and its juices, heat through without boiling, and sharpen with lemon and parsley."]} },

{ id:'raclette-valaisanne', c:'eu', lat:46.233, lon:7.360, base:6, prep:15, cook:20, diff:1, tags:['cheese','comfort','festive'],
  art:{v:'plate',bg:'#33301f',plate:'#f2e8d0',style:'flat',food:['#f0e0a8','#e8c46a','#f4ead4','#c9a24a'],garnish:'#7fae6a'},
  n:{fr:'Raclette valaisanne',en:'Valais raclette'},
  p:{fr:'Sion, Valais, Suisse',en:'Sion, Valais, Switzerland'},
  d:{fr:"Une demi-meule présentée au feu, dont on racle la surface fondue sur l'assiette — d'où le nom. Les bergers valaisans faisaient ainsi dès le Moyen Âge ; le poêlon électrique n'est venu que six siècles plus tard.",
     en:"Half a wheel held to the fire, its melting face scraped onto the plate — hence the name. Valais herdsmen did this from the Middle Ages; the electric grill arrived only six centuries later."},
  i:[['raclette_cheese',1.2,'kg'],['potato',1.5,'kg'],['pickles',200,'g'],['pearl_onions',150,'g'],['dried_beef',200,'g'],['black_peppercorns',1,'tbsp'],['paprika',1,'tsp'],['salt',null,'']],
  s:{fr:["Choisissez des pommes de terre à chair ferme, de calibre régulier, et cuisez-les en robe des champs 25 minutes.","Gardez-les au chaud sous un linge : elles doivent rester brûlantes tout le repas.","Présentez la demi-meule sous le gril, ou disposez les tranches dans les poêlons individuels.","Raclez le fromage dès qu'il boursoufle et coule, sans attendre qu'il colore.","Servez immédiatement sur la pomme de terre écrasée, avec cornichons, oignons au vinaigre et viande séchée. Poivrez au moulin."],
     en:["Choose firm-fleshed potatoes of even size and boil them in their skins for 25 minutes.","Keep them warm under a cloth: they must stay scalding throughout the meal.","Hold the half-wheel under the grill, or lay slices in individual pans.","Scrape the cheese the moment it blisters and runs, without waiting for it to colour.","Serve at once over the crushed potato, with gherkins, pickled onions and air-dried beef. Grind pepper over."]} },

{ id:'aelplermagronen', c:'eu', lat:47.050, lon:8.309, base:4, prep:20, cook:30, diff:1, tags:['comfort','cheese','veg'],
  art:{v:'pot',bg:'#2f3328',plate:'#f0e4c8',style:'noodle',food:['#f0e0bc','#e8c46a','#c9a878','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Macaronis de l’alpage',en:'Älplermagronen'},
  p:{fr:'Lucerne, Suisse',en:'Lucerne, Switzerland'},
  d:{fr:"Macaronis, pommes de terre, crème et fromage cuits dans la même casserole, avec des oignons frits et de la compote de pommes à côté. Les vachers d'alpage n'avaient qu'un feu et peu de vaisselle : tout va ensemble.",
     en:"Macaroni, potatoes, cream and cheese cooked in one pan, with fried onions and apple sauce on the side. Alpine herdsmen had one fire and little crockery: everything goes in together."},
  i:[['macaroni',300,'g'],['potato',400,'g'],['heavy_cream',300,'ml'],['whole_milk',200,'ml'],['gruyere_cheese',200,'g'],['onion',3,'pc'],['butter',60,'g'],['apple_sauce',400,'g'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Coupez les pommes de terre en dés de la taille des macaronis : ils doivent cuire ensemble.","Faites-les partir 5 minutes dans l'eau salée, puis ajoutez les pâtes pour le temps indiqué.","Pendant ce temps, faites blondir lentement les oignons émincés dans le beurre jusqu'à ce qu'ils dorent.","Égouttez, remettez dans la casserole avec la crème et le lait, et laissez réduire 3 minutes.","Hors du feu, incorporez le gruyère râpé et la muscade, couvrez d'oignons frits et servez avec la compote de pommes froide."],
     en:["Dice the potatoes to the size of the macaroni: they must cook together.","Start them in salted water for 5 minutes, then add the pasta for its stated time.","Meanwhile fry the sliced onions slowly in the butter until deep golden.","Drain, return to the pan with the cream and milk, and reduce for 3 minutes.","Off the heat, stir in the grated gruyère and the nutmeg, cover with the fried onions and serve with cold apple sauce."]} }
];

